package de.froehlichmedia.adaptkey.prediction

import de.froehlichmedia.adaptkey.dictionary.PartOfSpeech

/**
 * The output of a tier-3 [Tier3Provider.predictFamily] call (D-404): the requested word's category and
 * its whole inflectional family, generated by the model rather than merely looked up - unlike the non-LLM
 * path's [de.froehlichmedia.adaptkey.dictionary.LearnedLemmaLinking], which only ever links words already
 * genuinely typed and learned, this is proactive generation, exactly what the design calls for once a
 * tier-3 model is available.
 *
 * @property category the model's determined category, or null when it made no confident determination
 * @property lemma the family's own base/dictionary form - may equal the requested word itself when that
 *           word already is the base form
 * @property family every form worth learning, including [lemma] itself; empty when the model produced
 *           nothing usable (the caller then learns nothing beyond what the non-LLM path already did)
 */
data class Tier3FamilyResult(
    val category: PartOfSpeech?,
    val lemma: String,
    val family: List<String>
) {
    
    companion object {
        
        /** The empty result: no category, no lemma, no family - nothing for the caller to apply. */
        val EMPTY = Tier3FamilyResult(null, "", emptyList())
    }
}
